-- GA-EFB's setup: fetches the full setup from GA-EFB's website, checks it, and runs it. Press Run.
create extension if not exists http with schema extensions;
do $$
declare
  r extensions.http_response;
begin
  r := extensions.http_get('https://raw.githubusercontent.com/leontgiscombe/ga-efb-releases/gh-pages/setup/3fd5ae6612d6051c.sql');
  if r.status is distinct from 200 then
    raise exception 'GA-EFB''s setup couldn''t be downloaded (%). If GA-EFB was only just updated, try again in a few minutes.', r.status;
  end if;
  if encode(sha256(convert_to(r.content, 'UTF8')), 'hex') <> '3fd5ae6612d6051cfb1b666caae73a0b608c3b3163da1c5ae07df19e0e6f878b' then
    raise exception 'GA-EFB''s setup didn''t match this version of GA-EFB, so it wasn''t run.';
  end if;
  execute r.content;
end $$;
